import{_ as a,o as e,c as s,a2 as i}from"./chunks/framework.DTdEDYjJ.js";const b=JSON.parse('{"title":"连接与网络","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/network.md","filePath":"deployment/network.md"}'),d={name:"deployment/network.md"};function n(o,t,l,r,p,h){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="连接与网络" tabindex="-1">连接与网络 <a class="header-anchor" href="#连接与网络" aria-label="Permalink to &quot;连接与网络&quot;">​</a></h1><p>连接一个节点需要两件事：客户端能访问它的地址，并且持有该节点接受的凭据。账号登录、地址发现和网络连通分别解决不同问题。</p><h2 id="手机能不能连接自己的-mac" tabindex="-1">手机能不能连接自己的 Mac <a class="header-anchor" href="#手机能不能连接自己的-mac" aria-label="Permalink to &quot;手机能不能连接自己的 Mac&quot;">​</a></h2><p>可以采用这种运行方式：Mac 作为 Bot 主机，手机在同一 Wi-Fi 下配对访问，模型调用与任务仍由 Mac 执行。它不需要先购买云服务器，也不强制使用 Tailscale。</p><p>当前手机链路为独立Node/Hub预览原型，USB真实任务与LAN HTTPS配对/撤销分别已有验收；LAN真实模型任务、最新扫码真机与公网云Hub仍待验收。它没有与日常Mac App资料自动合并，不是在手机里登录账号就会自动接通。Mac 须保持开机、未休眠且服务运行，网络也须允许设备互通。现有手机 Web 客户端与原生客户端的证书要求需分别解决，不能把实验连接写成已支持。完整说明见<a href="/openbot/guide/requirements.html">使用门槛与运行方式</a>。</p><h2 id="连接自己的-node" tabindex="-1">连接自己的 Node <a class="header-anchor" href="#连接自己的-node" aria-label="Permalink to &quot;连接自己的 Node&quot;">​</a></h2><p>当前版本使用 <strong>SSH 隧道与 Node Bearer 令牌</strong>。Node 入口保留在服务器环回地址，Mac 将它转发到本机。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ExitOnForwardFailure=yes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ServerAliveInterval=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:14718:127.0.0.1:4718</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   your-server</span></span></code></pre></div><p><code>your-server</code> 是你已配置并核验主机密钥的 SSH 别名。保持这个连接运行，在 Mac 的节点设置中填写：</p><table tabindex="0"><thead><tr><th>字段</th><th>示例</th></tr></thead><tbody><tr><td>节点地址</td><td><code>http://127.0.0.1:14718</code></td></tr><tr><td>访问凭据</td><td>从自己节点取得的私有 Node 令牌</td></tr><tr><td>执行会话</td><td>保存设置后显式连接</td></tr></tbody></table><p>模型 Key 与 Node 令牌是两种凭据；阿里云账户密码和 SSH 私钥也不应填入模型配置。</p><h2 id="局域网、校园网与公网" tabindex="-1">局域网、校园网与公网 <a class="header-anchor" href="#局域网、校园网与公网" aria-label="Permalink to &quot;局域网、校园网与公网&quot;">​</a></h2><table tabindex="0"><thead><tr><th>网络情况</th><th>如何连接</th></tr></thead><tbody><tr><td>同一局域网，双方地址可达</td><td>使用受保护的节点入口或 SSH 转发</td></tr><tr><td>校园网有设备隔离或入站限制</td><td>先核对实际路由、防火墙和管理配置；同一网络名不保证设备互通</td></tr><tr><td>自己的云服务器有可达公网地址</td><td>当前优先 SSH；后续 Hub 可提供 HTTPS/WSS 入口</td></tr><tr><td>节点处于 NAT 后</td><td>可选私有组网或经可达 Hub 主动建立连接；后者尚未实现</td></tr></tbody></table><p>Tailscale 可以作为连接底座，现有 Node 可通过已配置的私网访问。OpenBot 不会自动安装 Tailscale、建立 tailnet 或接管其账户权限。公网不要直接暴露当前明文节点端口。</p><h2 id="断线、重连与接管" tabindex="-1">断线、重连与接管 <a class="header-anchor" href="#断线、重连与接管" aria-label="Permalink to &quot;断线、重连与接管&quot;">​</a></h2><p>每个 Node 同时只有一个执行控制客户端。连接租约失效后，旧审批和旧屏幕输入失效，旧请求不能换一个 ID 自动重派。</p><p>重连时应依次完成：</p><ol><li>恢复可达的连接，显式连接执行会话。</li><li>核对持久任务状态，处理离线期间的取消对账。</li><li>获取新画面；确认页面后显式交还人工控制。</li></ol><p>Node 重启后的未完任务标为中断。取消请求不撤销已经发生的网页操作；结果不确定时先查看任务和页面。</p><h2 id="hub-与设备配对" tabindex="-1">Hub 与设备配对 <a class="header-anchor" href="#hub-与设备配对" aria-label="Permalink to &quot;Hub 与设备配对&quot;">​</a></h2><p>独立开发原型采用以下分层；日常安装包整合、统一账号和自动发现尚未交付。Hub可以和Node一起放在自己的Mac或云服务器上：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>手机 / PC ── HTTPS/WSS ── 自托管 Hub ── 私有连接 ── Node</span></span>
<span class="line"><span>                              │                       └─ Bot 与浏览器</span></span>
<span class="line"><span>                              └─ 用户、设备与权限</span></span></code></pre></div><p>首次扫码携带 HTTPS Hub 地址和短期单次配对码。客户端保存地址，以后向同一 Hub 登录并读取获授权的 Bot。Hub 有可访问的 HTTPS 入口时，不要求安装 Tailscale。</p><p>如果要让全新设备仅登录账号就自动发现服务器，还需要可选的账号与节点目录。官方目录可以只保存归属和 Hub 地址，计算与数据继续留在用户服务器。</p><p>微信、支付宝、GitHub 或 Google 登录只负责身份验证。服务器归属、设备授权、Bot 权限和逐次执行审批仍需由 OpenBot 单独处理。</p><p>继续阅读：<a href="/openbot/deployment/hosted.html">官方托管规划</a> · <a href="/openbot/concepts/architecture.html">身份与执行架构</a>。</p>`,26)])])}const k=a(d,[["render",n]]);export{b as __pageData,k as default};
